// Dos servicios locales: tarifas (24715) y despachos (24716).
const http = require('http');
let modoTarifas = 'ok';
const tarifas = http.createServer((req, res) => {
  const u = new URL(req.url, 'http://x');
  if (modoTarifas === 'caido') { req.socket.destroy(); return; }
  const km = Number(u.searchParams.get('km'));
  const responder = () => { res.setHeader('content-type','application/json'); res.end(JSON.stringify({ precio: 1200 + km * 85 })); };
  if (modoTarifas === 'lento') setTimeout(responder, 3000); else responder();
}).listen(24715);

function pedirTarifa(km, ms) {
  return new Promise((ok, mal) => {
    const r = http.get(`http://127.0.0.1:24715/?km=${km}`, { agent: false }, (res) => {
      let b=''; res.on('data', d => b+=d); res.on('end', () => ok(JSON.parse(b)));
    });
    r.setTimeout(ms, () => { r.destroy(new Error('timeout')); });
    r.on('error', mal);
  });
}
const despachos = http.createServer(async (req, res) => {
  res.setHeader('content-type','application/json');
  try {
    const t = await pedirTarifa(14, 500);
    res.end(JSON.stringify({ estado: 'ok', precio: t.precio }));
  } catch (e) {
    res.statusCode = 503;
    res.end(JSON.stringify({ estado: 'sin_precio', motivo: e.message }));
  }
}).listen(24716);

function llamar(puerto) {
  return new Promise((ok) => {
    const t0 = process.hrtime.bigint();
    http.get(`http://127.0.0.1:${puerto}/`, { agent:false }, (res) => {
      let b=''; res.on('data', d=>b+=d);
      res.on('end', () => ok({ http: res.statusCode, ms: Number(process.hrtime.bigint()-t0)/1e6, cuerpo: b }));
    });
  });
}
// misma cuenta como llamada de función
const tarifaLocal = (km) => ({ precio: 1200 + km * 85 });

(async () => {
  let t0 = process.hrtime.bigint();
  for (let i=0;i<100000;i++) tarifaLocal(14);
  console.log('100000 llamadas de funcion: ' + (Number(process.hrtime.bigint()-t0)/1e6).toFixed(1) + ' ms en total');
  await llamar(24716); // calentar
  t0 = process.hrtime.bigint();
  for (let i=0;i<1000;i++) await llamar(24716);
  console.log('1000 llamadas despachos->tarifas por HTTP local: ' + (Number(process.hrtime.bigint()-t0)/1e6).toFixed(0) + ' ms en total');
  for (const m of ['ok','lento','caido']) {
    modoTarifas = m;
    const r = await llamar(24716);
    console.log(`tarifas=${m.padEnd(6)} -> HTTP ${r.http} en ${r.ms.toFixed(0)} ms ${r.cuerpo}`);
  }
  process.exit(0);
})();

