// Disponibilidad de un pedido que atraviesa n servicios en cadena.
// Cada uno con 99,9 %: es un supuesto de ejemplo, no la medición de nadie.
const porServicio = 0.999;
for (const n of [1, 3, 5, 10, 20]) {
  const total = Math.pow(porServicio, n);
  const minutosCaidos = (1 - total) * 30 * 24 * 60;
  console.log(
    String(n).padStart(2) + ' en cadena: ' +
    (total * 100).toFixed(2) + ' % disponible, ' +
    minutosCaidos.toFixed(0) + ' min caídos por mes'
  );
}
